from collections import Counter

def dominant_non5_color(block):
    """Find dominant non-5 color in block, or 5 if the block is empty"""
    non5_colors = []
    for row in block:
        for c in row:
            if c != 5:
                non5_colors.append(c)
    if not non5_colors:
        return 5
    counts = Counter(non5_colors)
    return counts.most_common(1)[0][0]

output_grid = []
for bi in range(3):
    row = []
    for bj in range(3):
        block = [[input_grid[r][c] for c in range(5*bj, 5*bj+5)] for r in range(5*bi, 5*bi+5)]
        dominant = dominant_non5_color(block)
        row.append(dominant)
        print(f"Block ({bi},{bj}): dominant non-5 = {dominant}")
    output_grid.append(row)

print(f"\nOutput grid (3x3): {output_grid}")

def dominant_non5_color_detail(block):
    """Find dominant non-5 color in block with counts"""
    non5_colors = []
    for row in block:
        for c in row:
            if c != 5:
                non5_colors.append(c)
    if not non5_colors:
        return 5, {}
    counts = Counter(non5_colors)
    return counts.most_common(1)[0][0], dict(counts)

output_grid = []
for bi in range(3):
    row = []
    print(f"\nRow {bi}:")
    for bj in range(3):
        block = [[input_grid[r][c] for c in range(5*bj, 5*bj+5)] for r in range(5*bi, 5*bi+5)]
        dominant, counts = dominant_non5_color_detail(block)
        row.append(dominant)
        print(f"Block ({bi},{bj}): counts={counts}, dominant={dominant}")
    output_grid.append(row)

print(f"\nOutput grid (3x3): {output_grid}")

